code.JavaScript:
const readline = require('readline').createInterface({
    input: process.stdin,
    output: process.stdout
});
let i = 0;
let t;
let input = [];
readline.on('line', line => {
    if (i === 0) {
        t = parseInt(line);
    } else {
        input.push(line.split(' ').map(num => parseInt(num)));
    }
    i++;
    if (i === t * 2 + 1) {
        for (let j = 0; j < t; j++) {
            let n = input[j * 2][0];
            let arr = input[j * 2 + 1];
            arr.sort((a, b) => b - a);
            let count = 1;
            for (let k = 1; k < n; k++) {
                if (arr[k] < arr[k-1]) {
                    count++;
                }
            }
            console.log(count);
        }
    }
});

